#!/bin/bash  # -*- mode: sh; sh-shell: bash -*--------------------------------------------------------------------------#  deploy.sh — Safe auto-deploy from GitHub  #  #  Called by cron every 3 minutes. Only deploys if origin/main has new  #  commits and the running container is healthy. Never deletes sources.  #  #  Usage: bash /opt/bot/deploy.sh  #--------------------------------------------------------------------------set -euo pipefail  BOT_DIR=${BOT_DIR:-/opt/bot}  CONTAINER=${CONTAINER:-quantum-bot}  cd ${BOT_DIR}  # Check container health first  if ! docker ps --format '{{.Names}}' | grep -qx ${CONTAINER}; then      echo >&2 $(date '+%F %T') [ERROR] Container ${CONTAINER} not running, skipping deploy      exit 1  fi  # Fetch latest commits without touching working tree  git fetch origin main --depth 1  LOCAL=$(git rev-parse HEAD)  REMOTE=$(git rev-parse origin/main)  if [ ${LOCAL} = ${REMOTE} ]; then      echo $(date '+%F %T') Up to date ${LOCAL}      exit 0  fi  echo $(date '+%F %T') Deploying ${LOCAL} -> ${REMOTE} ...  # Pull and rebuild  git pull origin main  docker-compose build --no-cache bot  docker-compose up -d --force-recreate bot  echo $(date '+%F %T') Deployed to ${REMOTE}  